const { S3Client, DeleteObjectCommand } = require('@aws-sdk/client-s3');
const s3 = new S3Client({});

exports.handler = async (event) => {
  const targetUserId = event.pathParameters.userId;
  const authenticatedUserId = event.requestContext.authorizer.claims.sub;
  if (targetUserId !== authenticatedUserId) {
    return { statusCode: 403, body: JSON.stringify({ error: 'Cannot delete avatar of another user' }) };
  }
  await s3.send(new DeleteObjectCommand({
    Bucket: process.env.AVATARS_BUCKET,
    Key: `profiles/${targetUserId}.png`
  }));
  return { statusCode: 200, body: JSON.stringify({ message: 'Profile avatar removed successfully' }) };
};
